<script setup>
import { ref, watch } from 'vue'
import SimulatedMeterPanel from './SimulatedMeterPanel.vue'
import { useEarlyModbusMqtt } from '@/composables/useEarlyModbusMqtt'
import { useMqttModbusSession } from '@/composables/useMqttModbusSession'
const editor = useEarlyModbusMqtt()
const { meterSupported, meterDirty, sessions, busy, error, ready, username, password, active: activeSession, topologyLocked, connect, stop, applyProfile, refresh } = useMqttModbusSession(editor)

const { templates, selectedTemplate, dataTab, gateways, selectedGatewayKey, activeGateway,
    devices, gatewayDevices, unboundDevices, visibleDevices, selectedDeviceId, activeDevice, deviceGateway, deviceDownTopic, deviceUpTopic, registerRows,
    meterGatewayKeys, meters, gatewayMeterCount, bindMeter,
    faultOptions, deviceAlarm, deviceSeverityClass, faultSummary, temperature, responsePreview, addressHex, queryFrame, responseFrame,
    gatewayId, brokerUrl, qos, interval, running, previewCount, lastPreview, logs, downTopic, upTopic,
    updateVersion, updateFault, isFaultSelected, numberRange, asciiChar, isAsciiAddress, fieldOptions,
    addDevice, removeDevice, updateAddress, gatewayDeviceCount, bindDevice, addGateway, removeGateway,
    selectGateway, setTemplate, togglePreview } = editor

function editMeter(type, key, value) {
  if (key === 'baudRateRaw') meters.value[type].baudRateRaw = value
  else meters.value[type].fields.find(field => field.key === key).value = value
}

function deviceOptionLabel(device) {
  const gateway = gateways.value.find((gateway) => gateway.key === device.gatewayKey)
  return `${device.name} · ${device.modelId} · 地址 ${device.address} · ${gateway?.name || '未绑定'}`
}

const deviceBindingOpen = ref(false)
const targetDeviceGatewayKey = ref('')

function openDeviceBinding() {
  if (topologyLocked.value || !activeDevice.value) return
  targetDeviceGatewayKey.value = deviceGateway.value?.key
    || gateways.value.find((gateway) => !gatewayMeterCount(gateway.key))?.key || ''
  deviceBindingOpen.value = true
}

function confirmDeviceBinding() {
  const device = activeDevice.value
  if (topologyLocked.value || !device || !targetDeviceGatewayKey.value || gatewayMeterCount(targetDeviceGatewayKey.value)) return
  bindDevice(device, targetDeviceGatewayKey.value)
  // 容量校验失败时保留选择区，供用户选择其他网关。
  if (device.gatewayKey === targetDeviceGatewayKey.value) deviceBindingOpen.value = false
}

// 切换查看对象或进入运行锁定后关闭选择区，避免把旧选择用于其他设备。
watch([() => activeDevice.value?.id, selectedGatewayKey, topologyLocked], () => {
  deviceBindingOpen.value = false
})
</script>

<template>
  <main class="early-modbus-mqtt">
    <div class="simulator-notice"><span class="notice-icon">i</span><div><strong>MQTT 查询应答模拟</strong><span>Java 服务接收 down 原始 RTU 查询，按网关绑定设备应答到 up；修改数据后需应用到运行会话。</span></div><span class="simulator-only">MQTT · RTU</span></div>

    <section class="simulator-hero">
      <div class="hero-copy"><div class="eyebrow"><i></i> MQTT TEST LAB <span>·</span> MODBUS RTU</div><h2>极早期设备协议模拟</h2><p>选择设备状态模板，预览寄存器值与 MQTT 主题下的报文。同一网关可绑定多台设备，每台设备只绑定一个网关。</p></div>
      <button class="btn" :class="running ? 'btn-stop' : 'btn-primary'" @click="togglePreview"><span class="run-symbol">{{ running ? '■' : '▶' }}</span>{{ running ? '停止预览' : '开始预览' }}</button>
      <div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div>
    </section>

    <div class="simulator-grid">
      <section class="simulator-card connection-card">
        <header class="card-heading connection-heading">
          <div class="heading-icon cyan">↔</div><div class="connection-title"><h3>MQTT 连接配置</h3><p>{{ gateways.length }} 个网关 · 每个网关独立配置主题和参数</p></div>
          <div class="gateway-header-controls">
            <button class="mini-action" :disabled="topologyLocked || gateways.length >= 8" @click="addGateway(false)">添加网关</button><button class="mini-action" :disabled="topologyLocked || gateways.length >= 8" @click="addGateway(true)">复制当前</button><button class="mini-action gateway-delete" :disabled="topologyLocked || gateways.length === 1" :title="gateways.length === 1 ? '至少保留一个网关' : '删除网关并迁移其设备'" @click="removeGateway(activeGateway)">删除</button>
            <select :value="selectedGatewayKey" class="gateway-header-select" aria-label="选择网关" @change="selectGateway(gateways.find(gateway => gateway.key === $event.target.value))"><option v-for="gateway in gateways" :key="gateway.key" :value="gateway.key">{{ gateway.name.replace(/\s+/g, '') }}→{{ gatewayDeviceCount(gateway.key) }}台设备</option></select>
            <span class="pill pill-off"><i></i>{{ activeSession?.state || '未连接' }}</span>
          </div>
        </header>
        <fieldset class="config-fields" :disabled="!!activeSession || busy || !ready">
          <label class="simulator-field wide"><span>Broker 地址</span><input v-model="brokerUrl" class="input" aria-label="Broker 地址" placeholder="mqtt://主机:1883"><small>支持 mqtt:// 或 tcp://；MQTT 3.1.1，原始二进制应答</small></label>
          <label class="simulator-field"><span>网关 ID</span><input v-model="gatewayId" class="input" aria-label="网关 ID"></label>
          <label class="simulator-field"><span>QoS</span><select v-model="qos" class="input" aria-label="QoS"><option value="0">0 · 最多一次</option><option value="1">1 · 至少一次</option><option value="2">2 · 恰好一次</option></select></label>
          <label class="simulator-field"><span>预览间隔</span><select v-model="interval" class="input" aria-label="预览间隔"><option value="1000">1 秒</option><option value="2000">2 秒</option><option value="5000">5 秒</option></select></label>
          <label class="simulator-field"><span>Client ID（留空自动生成）</span><input v-model="activeGateway.clientId" class="input" aria-label="Client ID"></label>
          <label class="simulator-field"><span>用户名（可选）</span><input v-model="username" class="input" autocomplete="off"></label>
          <label class="simulator-field"><span>密码（连接后清空）</span><input v-model="password" class="input" type="password" autocomplete="new-password"></label>
          <label class="simulator-field wide"><span>自定义下行主题（电表使用固定主题）</span><input v-model="activeGateway.downTopic" class="input" :disabled="!!gatewayMeterCount(selectedGatewayKey)"></label>
          <label class="simulator-field wide"><span>自定义上行主题（电表使用固定主题）</span><input v-model="activeGateway.upTopic" class="input" :disabled="!!gatewayMeterCount(selectedGatewayKey)"></label>
        </fieldset>
        <div class="topic-list"><div class="topic-row"><span class="topic-tag down">SUB</span><div><small>下行订阅主题</small><code>{{ downTopic }}</code></div><span class="topic-state">查询请求</span></div><div class="topic-row"><span class="topic-tag up">PUB</span><div><small>上行发布主题</small><code>{{ upTopic }}</code></div><span class="topic-state">设备响应</span></div></div>
        <div class="mqtt-actions"><button class="btn btn-primary" :disabled="busy || !ready || !!activeSession || (!gatewayMeterCount(selectedGatewayKey) && !gatewayDevices.length) || (!!gatewayMeterCount(selectedGatewayKey) && !meterSupported)" @click="connect">连接当前网关</button><button class="btn" :disabled="busy || !activeSession" @click="stop">停止当前网关</button><button class="btn" :disabled="busy" @click="refresh">刷新状态</button></div>
        <p v-if="gatewayMeterCount(selectedGatewayKey)" class="mqtt-hint">此网关绑定 {{ gatewayMeterCount(selectedGatewayKey) }} 块电表，使用电表固定主题；连接后按地址 1/2 应答，采用旧监测程序兼容编码。</p>
        <p v-if="error" class="mqtt-error" role="alert">{{ error }}</p>
        <p class="mqtt-hint">同时运行 {{ sessions.length }}/8 个网关。收到查询后才应答；离开页面停止续租，60 秒内释放连接。</p>
        <p v-if="activeSession" class="mqtt-hint">配置版本 {{ activeSession.version }} · 收到 {{ activeSession.received }} · 发布 {{ activeSession.published }} · 过滤 {{ activeSession.filtered || 0 }} · 丢弃 {{ activeSession.dropped }} · {{ activeSession.error }}</p>
      </section>

      <section class="simulator-card device-card">
        <header class="card-heading device-heading">
          <div class="heading-icon violet">▦</div><div class="device-title"><h3>模拟设备</h3><p>{{ activeGateway.name }} 已绑定 {{ gatewayDevices.length }} 台设备 · {{ unboundDevices.length }} 台未绑定</p></div>
          <div class="device-header-controls">
            <button class="mini-action" :disabled="topologyLocked || !!gatewayMeterCount(selectedGatewayKey)" @click="addDevice(false)">添加设备</button><button class="mini-action" :disabled="topologyLocked || !activeDevice || !!gatewayMeterCount(selectedGatewayKey)" @click="addDevice(true)">复制当前</button><button class="mini-action delete-action" :disabled="topologyLocked || !activeDevice || devices.length === 1" :title="devices.length === 1 ? '至少保留一台设备' : '移除当前设备'" @click="removeDevice(activeDevice)">移除当前</button>
            <select :value="activeDevice?.id || ''" class="device-header-select" aria-label="选择模拟设备" :disabled="!visibleDevices.length" :title="activeDevice ? deviceOptionLabel(activeDevice) : '暂无可选设备'" @change="selectedDeviceId = $event.target.value"><option v-if="!visibleDevices.length" value="">暂无可选设备</option><option v-for="device in visibleDevices" :key="device.id" :value="device.id">{{ device.name }}→地址{{ device.address }}</option></select>
          </div>
        </header>
        <p v-if="gatewayMeterCount(selectedGatewayKey)" class="mqtt-hint">此网关已用于电表，下方仍展示全部极早期设备供查看、编辑和报文预览。查看不会改变设备绑定。</p>
        <div v-if="!activeDevice" class="device-empty">此网关尚未绑定设备。可以添加设备，也可以切换到其他网关，在设备的“绑定 MQTT 网关”中选择此网关。</div>
        <template v-else>
        <fieldset class="selected-device-fields" :disabled="topologyLocked">
          <label class="simulator-field"><span>设备名称</span><input v-model="activeDevice.name" class="input"></label>
          <label class="simulator-field"><span>设备标识</span><input v-model="activeDevice.modelId" class="input"></label>
          <label class="simulator-field"><span>Modbus 从站地址（1–247）</span><input :value="activeDevice.address" class="input" type="number" min="1" max="247" @change="updateAddress(activeDevice, $event.target.value); $event.target.value = activeDevice.address"></label>
        </fieldset>
        <div class="device-binding-panel" aria-label="设备网关绑定">
          <div class="binding-status"><div><strong>{{ deviceGateway ? `已绑定 ${deviceGateway.name}` : '尚未绑定网关' }}</strong><small v-if="deviceGateway">{{ deviceGateway.gatewayId }} · {{ deviceGateway.brokerUrl || '未填写 Broker' }}</small></div><button type="button" class="binding-button" :disabled="topologyLocked" :aria-expanded="deviceBindingOpen" aria-controls="device-binding-picker" @click="openDeviceBinding">{{ deviceGateway ? '更换网关' : '绑定网关' }}</button></div>
          <div v-if="deviceBindingOpen" id="device-binding-picker" class="binding-picker">
            <label>选择网关<select v-model="targetDeviceGatewayKey" aria-label="设备绑定网关"><option v-if="!targetDeviceGatewayKey" value="" disabled>暂无可用网关</option><option v-for="gateway in gateways" :key="gateway.key" :value="gateway.key" :disabled="!!gatewayMeterCount(gateway.key)">{{ gateway.name }} · {{ gateway.gatewayId }}（{{ gatewayMeterCount(gateway.key) ? '已绑定电表' : `${gatewayDeviceCount(gateway.key)} 台设备` }}）</option></select></label>
            <p>一台设备只能绑定一个网关；已绑定电表的网关不可选择。同一网关内地址冲突时自动分配空闲地址。</p>
            <div class="binding-actions"><button type="button" class="binding-button primary" :disabled="topologyLocked || !targetDeviceGatewayKey || !!gatewayMeterCount(targetDeviceGatewayKey)" @click="confirmDeviceBinding">确认绑定</button><button type="button" class="binding-button" @click="deviceBindingOpen = false">取消</button></div>
          </div>
          <p v-if="topologyLocked" class="binding-lock">请等待会话状态确认，并停止全部运行网关后再修改绑定。</p>
        </div>
        <div v-if="deviceGateway" class="device-route" aria-label="设备 MQTT 路由"><span>{{ activeDevice.name }}（地址 {{ activeDevice.address }}） → {{ deviceGateway.name }}</span><span>Broker：{{ deviceGateway.brokerUrl }}</span><code>SUB {{ deviceDownTopic }}</code><code>PUB {{ deviceUpTopic }}</code><small>切换绑定后使用目标网关的主题；同一网关内地址冲突时自动分配空闲地址。</small></div>
        <div v-else class="device-route">{{ activeDevice.name }} 尚未绑定网关，数据已保留；请先选择可用网关。</div>
        <div class="template-tabs" role="tablist" aria-label="设备数据模板"><button v-for="(label, key) in templates" :key="key" :class="[{ active: selectedTemplate === key }, `tab-${key}`]" @click="setTemplate(key)"><i></i>{{ label }}</button></div>
        <div class="device-summary"><div class="device-glyph" :class="`glyph-${deviceSeverityClass}`"><span>⌁</span><i></i></div><div class="device-name"><strong>{{ activeDevice.name }} <small>{{ activeDevice.modelId }}</small></strong><span><i :class="`state-${deviceSeverityClass}`"></i>{{ deviceSeverityClass === 'normal' ? '正常' : deviceSeverityClass === 'alarm' ? '报警' : '故障' }} · 本地预览</span></div><span class="severity" :class="`severity-${deviceSeverityClass}`">{{ deviceAlarm }}</span></div>
        <div class="measure-grid"><div class="measure"><span>烟雾实时曲线</span><strong>{{ activeDevice.inputRegisters[0] }}</strong><em>输入寄存器 0x0001</em></div><div class="measure"><span>故障类型</span><strong class="alarm-value">{{ faultSummary }}</strong><em>输入寄存器 0x0002 位图</em></div><div class="measure"><span>报警级别</span><strong class="alarm-value">{{ deviceAlarm }}</strong><em>输入寄存器 0x0003</em></div><div class="measure"><span>环境温度 / 湿度 / 电压</span><strong>{{ temperature }} / {{ (activeDevice.inputRegisters[15] / 100).toFixed(2) }}% / {{ (activeDevice.inputRegisters[16] / 100).toFixed(2) }}V</strong><em>输入寄存器 0x000F–0x0011</em></div></div>
        </template>
      </section>

      <section class="simulator-card registers-card">
        <header class="card-heading registers-heading">
          <div class="heading-icon blue">▤</div><div><h3>设备数据编辑</h3><p>根据协议地址表编辑全部输入寄存器、保持寄存器与线圈</p></div>
          <select :value="activeDevice?.id || ''" class="editor-header-select" aria-label="选择编辑设备" :disabled="!visibleDevices.length" @change="selectedDeviceId = $event.target.value"><option v-if="!visibleDevices.length" value="">暂无可选设备</option><option v-for="device in visibleDevices" :key="device.id" :value="device.id">{{ device.name }}</option></select>
        </header>
        <template v-if="activeDevice">
        <div class="data-tabs" role="tablist"><button :class="{ active: dataTab === 'input' }" @click="dataTab = 'input'">输入寄存器 <small>0x04 · 63</small></button><button :class="{ active: dataTab === 'holding' }" @click="dataTab = 'holding'">保持寄存器 <small>0x03 · 39</small></button><button :class="{ active: dataTab === 'coils' }" @click="dataTab = 'coils'">线圈 <small>0x01 · 10</small></button></div>
        <div v-if="dataTab === 'input'" class="version-editors">
          <label><span>设备序列号</span><input :value="activeDevice.serialNumber" maxlength="11" @input="updateVersion(activeDevice, 'serialNumber', 0x17, 11, $event.target.value)"><small>0x17–0x21 · 11 个 ASCII 字符</small></label>
          <label><span>硬件版本</span><input :value="activeDevice.hardwareVersion" maxlength="14" @input="updateVersion(activeDevice, 'hardwareVersion', 0x22, 14, $event.target.value)"><small>0x22–0x2F · 14 个 ASCII 字符 · 示例：F2J1D4B3A12.16</small></label>
          <label><span>软件版本</span><input :value="activeDevice.softwareVersion" maxlength="16" @input="updateVersion(activeDevice, 'softwareVersion', 0x30, 16, $event.target.value)"><small>0x30–0x3F · 地址范围共 16 格；示例版本含 15 字符，末格填 00</small></label>
          <p>编码推断：每个地址存一个 ASCII 字符，字符码放在 16 位寄存器低字节，高字节为 00。协议文字称软件版本 14 字节，与 0x30–0x3F 的 16 个地址不一致，示例按 15 个字符加 00 填充，仍需现场报文确认。</p>
        </div>
        <div class="register-table editable-table"><div class="register-head"><span>地址</span><span>协议字段</span><span>{{ dataTab === 'coils' ? '开关' : '数值 / 选择' }}</span><span>HEX / ASCII</span></div><div v-for="row in registerRows" :key="`${dataTab}-${row.address}`" class="register-row"><code>0x{{ row.address.toString(16).padStart(4, '0').toUpperCase() }}</code><span :title="row.name">{{ row.name }}</span><label v-if="dataTab === 'coils'" class="coil-toggle"><input v-model="activeDevice.coils[row.address - 1]" type="checkbox"><span>{{ activeDevice.coils[row.address - 1] ? 'ON' : 'OFF' }}</span></label><details v-else-if="dataTab === 'input' && row.address === 2" class="fault-picker"><summary>{{ faultSummary }}</summary><div class="fault-options"><label v-for="option in faultOptions" :key="option.bit"><input type="checkbox" :checked="isFaultSelected(option.bit)" @change="updateFault(option.bit, $event.target.checked)"><span>{{ option.label }}</span></label></div></details><span v-else-if="dataTab === 'input' && isAsciiAddress(row.address)" class="version-char">{{ asciiChar(row.address) }}</span><select v-else-if="fieldOptions(dataTab, row.address, row.value).length" v-model.number="activeDevice[dataTab === 'input' ? 'inputRegisters' : 'holdingRegisters'][row.address - 1]" class="register-input"><option v-for="option in fieldOptions(dataTab, row.address, row.value)" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else v-model.number="activeDevice[dataTab === 'input' ? 'inputRegisters' : 'holdingRegisters'][row.address - 1]" class="register-input" type="number" :min="numberRange(dataTab, row.address)[0]" :max="numberRange(dataTab, row.address)[1]" :aria-label="`${row.name} 数值`"><code v-if="dataTab !== 'coils'" class="register-hex">{{ Number(activeDevice[dataTab === 'input' ? 'inputRegisters' : 'holdingRegisters'][row.address - 1] || 0).toString(16).padStart(4, '0').toUpperCase() }}<small v-if="dataTab === 'input' && isAsciiAddress(row.address)"> · {{ asciiChar(row.address) }}</small></code><code v-else class="register-hex">{{ activeDevice.coils[row.address - 1] ? '0001' : '0000' }}</code></div></div>
        <div class="mqtt-actions"><button class="btn btn-primary" :disabled="busy || activeSession?.state !== 'RUNNING' || activeDevice.gatewayKey !== selectedGatewayKey" @click="applyProfile">应用当前网关设备数据</button></div><div class="register-foot"><span><i></i>编辑值实时反映到预览，运行数据需点击应用</span><span>切换工具保留，刷新后重置</span></div>
        </template>
        <p v-else class="device-empty">选择极早期设备后编辑数据。</p>
      </section>

      <SimulatedMeterPanel :meters="meters" :sessions="sessions" :busy="busy" :supported="meterSupported" :dirty="meterDirty" :gateways="gateways" :bindings="meterGatewayKeys" :devices="devices" :locked="topologyLocked" @bind="(type, key) => !topologyLocked && bindMeter(type, key)" @edit="editMeter" @apply="applyProfile" />
    </div>

    <div class="simulator-grid activity-grid">
      <section class="simulator-card activity-card">
        <header class="activity-head"><div class="card-heading"><div class="heading-icon green">≋</div><div><h3>模拟活动</h3><p>本地预览与 MQTT 接收、发布、异常记录</p></div></div><div class="activity-metrics"><span>预览次数 <b>{{ previewCount }}</b></span><span>最近预览 <b>{{ lastPreview }}</b></span></div></header>
        <div class="activity-body"><div class="log-head"><span>时间</span><span>类型</span><span>事件</span><span>结果</span></div><div v-for="(log, index) in logs" :key="`${log.time}-${index}`" class="log-row"><time>{{ log.time }}</time><span class="log-kind" :class="`kind-${log.kind === '模拟' ? 'sim' : log.kind === '系统' ? 'system' : 'preview'}`">{{ log.kind }}</span><span>{{ log.message }}</span><span class="local-result">记录</span></div></div>
      </section>

      <section class="simulator-card frames-card">
        <header class="card-heading"><div class="heading-icon orange">⌘</div><div><h3>报文预览</h3><p>Modbus RTU 查询与响应样例</p></div><span class="preview-label">静态预览</span></header>
        <label class="simulator-field selection-field"><span>选择预览设备</span><select :value="activeDevice?.id || ''" class="input" aria-label="选择报文预览设备" :disabled="!visibleDevices.length" @change="selectedDeviceId = $event.target.value"><option v-if="!visibleDevices.length" value="">暂无可选设备</option><option v-for="device in visibleDevices" :key="device.id" :value="device.id">{{ deviceOptionLabel(device) }}</option></select><small>与模拟设备选择同步，展示所选设备的查询和响应</small></label>
        <template v-if="activeDevice">
        <div v-if="deviceGateway" class="device-route"><span>{{ activeDevice.name }} → {{ deviceGateway.name }}</span><code>SUB {{ deviceDownTopic }}</code><code>PUB {{ deviceUpTopic }}</code></div>
        <div v-else class="device-route">{{ activeDevice.name }} · 未绑定网关，仅预览本地报文；绑定后才有 MQTT 发布目标。</div>
        <div class="frame-block"><div class="frame-title"><span class="frame-direction tx">TX <i>下行查询</i></span><small>FC 04 · 读取输入寄存器 1–22</small></div><code>{{ queryFrame }}</code></div>
        <div class="frame-block"><div class="frame-title"><span class="frame-direction rx">RX <i>上行响应</i></span><small>{{ activeDevice.name }} · {{ activeDevice.address }} 号站</small></div><code>{{ responseFrame }}</code></div>
        <p class="crc-note">末尾两字节为 RTU CRC（低字节先发）。此处为编辑草稿预览，实际应答内容以运行版本与收发事件为准。</p>
        </template>
        <p v-else class="device-empty">选择极早期设备后预览本地报文。</p>
